create table personel_listesi
(
personel_ID int primary key not null,
adı varchar(20) not null,
soyadı varchar(20) not null,
yaş int not null,
medeni_durumu varchar(20) not null,
cinsiyet varchar(2) not null,
dogum_yeri varchar(20) not null,
uyruğu varchar(20) not null,
kıdem_yılı int not null,
maaş int not null,
çalıştıgı_bolum varchar(20) not null,
eğitim_durumu varchar(20) not null,
yabancı_dil varchar(20) not null,
yabancı_dili2 varchar(20) not null,
eposta varchar(40) not null,
telefon_numarası varchar(20) not null,
adres varchar(20),
)









